[Thinking]
**Considering conversion options**

I need to create a Qt5 app that uses QFileDialog to select a directory and list .xls/.xlsx files for conversion to CSV. The tricky part is that Excel conversion needs a library. Using Qt alone is challenging here. I could utilize QAxObject on Windows for COM automation, or look into a third-party option like libxlsxwriter, but that’s only for writing. I'll go with an example using QAxObject and provide main.cpp, keeping it concise.
[/Thinking]

Below is a minimal Qt5 example (for Windows) that:

1. Shows a simple GUI with a “Select Folder and Convert” button.  
2. Prompts the user to select a directory.  
3. Finds all `.xls` and `.xlsx` files in that directory.  
4. Uses `QAxObject` (COM automation of Microsoft Excel) to convert each Excel file to CSV.  
5. Places the CSVs in a new subfolder named `csv_output` in the selected directory.

This uses Qt’s ActiveQt module (`QAxObject`), so it requires:
- Windows
- Microsoft Excel installed  
- `QT += axcontainer` (or `axobject` depending on Qt version) in `.pro` file

---

### Project file (example `.pro`)

```pro
QT       += core gui axcontainer

greaterThan(QT_MAJOR_VERSION, 4): QT += widgets

TARGET = ExcelToCsvConverter
TEMPLATE = app

SOURCES += main.cpp \
           mainwindow.cpp

HEADERS += mainwindow.h
```

---

### `mainwindow.h`

```cpp
#ifndef MAINWINDOW_H
#define MAINWINDOW_H

#include <QMainWindow>

class QPushButton;
class QTextEdit;

class MainWindow : public QMainWindow
{
    Q_OBJECT

public:
    explicit MainWindow(QWidget *parent = nullptr);

private slots:
    void onSelectDirectoryAndConvert();

private:
    void logMessage(const QString &msg);

    QPushButton *convertButton;
    QTextEdit   *logView;
};

#endif // MAINWINDOW_H
```

---

### `mainwindow.cpp`

```cpp
#include "mainwindow.h"

#include <QPushButton>
#include <QTextEdit>
#include <QVBoxLayout>
#include <QWidget>
#include <QFileDialog>
#include <QDir>
#include <QFileInfoList>
#include <QMessageBox>
#include <QAxObject>    // ActiveQt
#include <QFileInfo>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
{
    auto *central = new QWidget(this);
    auto *layout = new QVBoxLayout(central);

    convertButton = new QPushButton("Select Folder and Convert Excel to CSV", this);
    logView = new QTextEdit(this);
    logView->setReadOnly(true);

    layout->addWidget(convertButton);
    layout->addWidget(logView);

    setCentralWidget(central);
    resize(600, 400);
    setWindowTitle("Excel to CSV Converter (Qt5)");

    connect(convertButton, &QPushButton::clicked,
            this, &MainWindow::onSelectDirectoryAndConvert);
}

void MainWindow::logMessage(const QString &msg)
{
    logView->append(msg);
}

void MainWindow::onSelectDirectoryAndConvert()
{
    QString dirPath = QFileDialog::getExistingDirectory(
        this,
        "Select directory containing Excel files",
        QString(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (dirPath.isEmpty())
        return;

    QDir dir(dirPath);
    if (!dir.exists()) {
        QMessageBox::warning(this, "Error", "Selected directory does not exist.");
        return;
    }

    // Get all .xls and .xlsx files
    QStringList filters;
    filters << "*.xls" << "*.xlsx";
    QFileInfoList fileList = dir.entryInfoList(filters, QDir::Files | QDir::NoSymLinks);

    if (fileList.isEmpty()) {
        QMessageBox::information(this, "No Excel files", "No .xls or .xlsx files found.");
        return;
    }

    // Create output directory
    QString outDirPath = dirPath + QDir::separator() + "csv_output";
    QDir outDir(outDirPath);
    if (!outDir.exists()) {
        if (!dir.mkdir("csv_output")) {
            QMessageBox::warning(this, "Error", "Could not create output directory.");
            return;
        }
    }

    logView->clear();
    logMessage("Starting conversion...");
    logMessage("Input directory: " + dirPath);
    logMessage("Output directory: " + outDirPath);

    // Start Excel via COM
    QAxObject excel("Excel.Application");
    if (excel.isNull()) {
        QMessageBox::critical(this, "Error", "Could not start Microsoft Excel (COM).");
        return;
    }

    excel.setProperty("Visible", false);
    QAxObject *workbooks = excel.querySubObject("Workbooks");
    if (!workbooks) {
        QMessageBox::critical(this, "Error", "Could not access Excel workbooks.");
        return;
    }

    // Excel CSV file format code (24 = xlCSV)
    const int xlCSV = 24;

    for (const QFileInfo &fi : fileList) {
        QString inFile = fi.absoluteFilePath();
        QString baseName = fi.completeBaseName(); // filename without extension
        QString outFile = outDirPath + QDir::separator() + baseName + ".csv";

        logMessage(QString("\nConverting: %1").arg(inFile));

        // Open workbook
        QAxObject *workbook = workbooks->querySubObject(
            "Open(const QString&)", inFile);
        if (!workbook || workbook->isNull()) {
            logMessage("  ERROR: Could not open file in Excel.");
            continue;
        }

        QAxObject *activeSheet = workbook->querySubObject("ActiveSheet");
        if (!activeSheet) {
            logMessage("  ERROR: Could not get active sheet.");
            workbook->dynamicCall("Close(bool)", false);
            delete workbook;
            continue;
        }

        // Save as CSV
        QVariantList params;
        params << outFile      // Filename
               << xlCSV        // FileFormat
               << QVariant()   // Password
               << QVariant()   // WriteResPassword
               << false        // ReadOnlyRecommended
               << false        // CreateBackup
               << 6            // Local (xlLocal)
               << QVariant();  // AddBackup etc. (depends on version)

        bool ok = workbook->dynamicCall("SaveAs(const QVariant&, const QVariant&, const QVariant&, "
                                         "const QVariant&, const QVariant&, const QVariant&, "
                                         "const QVariant&, const QVariant&, const QVariant&, "
                                         "const QVariant&, const QVariant&)",
                                         params).isValid();
        if (!ok) {
            logMessage("  ERROR: SaveAs to CSV failed.");
        } else {
            logMessage("  Success -> " + outFile);
        }

        workbook->dynamicCall("Close(bool)", false);
        delete workbook;
    }

    // Quit Excel
    excel.dynamicCall("Quit()");

    logMessage("\nConversion finished.");
    QMessageBox::information(this, "Done", "Conversion complete. See csv_output folder.");
}
```

---

### `main.cpp`

```cpp
#include "mainwindow.h"
#include <QApplication>

int main(int argc, char *argv[])
{
    QApplication a(argc, argv);

    MainWindow w;
    w.show();

    return a.exec();
}
```

---

### Notes

- This example uses COM automation via `QAxObject`, so it only works on Windows with Excel installed.
- If you need a cross‑platform solution, you’d have to use a library that can read XLS/XLSX (e.g., POCO, xlnt, OpenXLSX, or call a command-line tool like `libreoffice --headless --convert-to csv`) and adapt the conversion logic accordingly.

